definition.sw_read():
Bits<64> value = $bits(CSR[henvcfg]);
if (implemented?(ExtensionName::Sstc) && CSR[menvcfg].STCE == 0) {
  # henvcfg.STCE must read-as-zero
  value = value & ~(1 `<< 63);
}
if (implemented?(ExtensionName::Svpbmt) && CSR[menvcfg].PBMTE == 0) {
  # henvcfg.PBMTE must read-as-zero
  value = value & ~(1 `<< 62);
}
if (implemented?(ExtensionName::Svadu) && CSR[menvcfg].ADUE == 0) {
  # henvcfg.ADUE must read-as-zero
  value = value & ~(1 `<< 61);
}
if (implemented?(ExtensionName::Zicfiss) && CSR[menvcfg].SSE == 0) {
  # henvcfg.SSE must read-as-zero
  value = value & ~(1 `<< 3);
}
return value;

MODE.sw_write(csr_value):
if (csr_value.MODE == $bits(HgatpMode::Bare)) {
  if (!GSTAGE_MODE_BARE) {
    return UNDEFINED_LEGAL_DETERMINISTIC;
  }
}

if (csr_value.MODE == $bits(HgatpMode::Sv32x4)) {
  if (!SV32X4_TRANSLATION) {
    return UNDEFINED_LEGAL_DETERMINISTIC;
  }
}

if (csr_value.MODE == $bits(HgatpMode::Sv39x4)) {
  if (!SV39X4_TRANSLATION) {
    return UNDEFINED_LEGAL_DETERMINISTIC;
  }
}

if (csr_value.MODE == $bits(HgatpMode::Sv48x4)) {
  if (!SV48X4_TRANSLATION) {
    return UNDEFINED_LEGAL_DETERMINISTIC;
  }
}

if (csr_value.MODE == $bits(HgatpMode::Sv57x4)) {
  if (!SV57X4_TRANSLATION) {
    return UNDEFINED_LEGAL_DETERMINISTIC;
  }
}

# mode is supported
return csr_value.MODE;

