definition.sw_read():
XReg res = 0;

# SGEIP: 1 iff bitwise AND of hgeip and hgeie is nonzero
if (($bits(CSR[hgeie]) & $bits(CSR[hgeip])) != 0) {
  res[12] = 1'b1;
}

# VSEIP: logical OR of hvip.VSEIP and platform-specific sources
if (CSR[hvip].VSEIP == 1'b1) {
  res[10] = 1'b1;
}

# VSTIP: logical OR of hvip.VSTIP and vstimecmp comparison (if Sstc)
if (implemented?(ExtensionName::Sstc)) {
  if ((CSR[hvip].VSTIP == 1'b1) || ((read_mtime() + CSR[htimedelta].DELTA) >= CSR[vstimecmp].TIME)) {
    res[6] = 1'b1;
  }
} else {
  if (CSR[hvip].VSTIP == 1'b1) {
    res[6] = 1'b1;
  }
}

# VSSIP: alias of hvip.VSSIP
if (CSR[hvip].VSSIP == 1'b1) {
  res[2] = 1'b1;
}

return res;

VSSIP.sw_write(csr_value):
# VSSIP in hip is an alias of VSSIP in hvip
CSR[hvip].VSSIP = csr_value.VSSIP;
return csr_value.VSSIP;

