definition.sw_read():
# CSRRS/CSRRC/CSRRSI/CSRRCI are the CSR instructions with funct3[1] set.
# Bits 19:15 hold rs1 for the register forms and uimm for the immediate
# forms, so a single zero check covers rs1 == x0 and uimm == 0.
Boolean read_only_access = ($encoding[13] == 1'b1) && ($encoding[19:15] == 5'b00000);

if (read_only_access) {
  raise(ExceptionCode::IllegalInstruction, mode(), $encoding);
}

if (mode() == PrivilegeMode::U && CSR[mseccfg].USEED == 1'b0) {
  raise(ExceptionCode::IllegalInstruction, mode(), $encoding);
} else if (mode() == PrivilegeMode::S && CSR[mseccfg].SSEED == 1'b0) {
  raise(ExceptionCode::IllegalInstruction, mode(), $encoding);
} else if (mode() == PrivilegeMode::VS || mode() == PrivilegeMode::VU) {
  if (CSR[mseccfg].SSEED == 1'b1) {
    raise(ExceptionCode::VirtualInstruction, mode(), $encoding);
  } else {
    raise(ExceptionCode::IllegalInstruction, mode(), $encoding);
  }
}

# A single poll returns both the status and the entropy it goes with.
return read_seed();

# access is determined by *counteren CSRs
if (mode() == PrivilegeMode::S) {
  # S-mode is present ->
  #   mcounteren determines access in S-mode
  if (CSR[mcounteren].CY == 1'b0) {
    raise(ExceptionCode::IllegalInstruction, mode(), $encoding);
  }
